"""Create the full 331 review/332 decision report and standalone accessible index."""
from pathlib import Path
from html import escape
import hashlib,json
R=Path('/home/user');A=R/'archive/task305_331_review_332';Q=A/'analysis';S=A/'stage';J=lambda p:json.loads(p.read_text());H=lambda p:hashlib.sha256(p.read_bytes()).hexdigest();retro=J(Q/'retrospective.json');audit=J(Q/'candidate_audit.json');qc=J(Q/'candidate_independent_qc.json');corr=J(Q/'manual_stage_correction.json');assert qc['status']==J(Q/'review_independent_qc.json')['status']=='PASS' and corr['status']=='PASS_STAGING_ONLY_WORDING_CORRECTED' and corr['new_decisions_sha256']==H(S/'data/manual_site_decisions.json') and audit['choice']=='HH01' and not audit['target_332_result_queried_or_used'];records=retro['historical_outcomes'];recon=retro['unpublished_reconstructions'];cands=audit['candidates'];lookup={x['id']:x for x in cands};assert len(records)==38 and len(recon)==3 and len(cands)==16
report=R/'331期复盘_332期方案与逐期核验.md';index=S/'2026332-index.html';assert not report.exists() and not index.exists()
def cell(s):return f"{''.join(s['required'])} {s['present_count']}/{s['needed_count']}（中{''.join(s['present']) or '—'}；缺{''.join(s['missing']) or '—'}）"
def historical_table(xs,source=False):
 header='| 期 | '+('来源 | ' if source else '性质 | ')+'单：命中／缺失 | 二：命中／缺失 | 三：命中／缺失 | 完整栏 |\n|---:|---|---|---|---|---:|\n';parts=[]
 for x in xs:
  label=('留存栏目文件' if x['period']<=2026308 else 'Git页面快照') if source else '事后重建';parts.append('| '+str(x['period']%1000)+' | '+label+' | '+' | '.join(cell(s) for s in x['slots'])+' | '+str(x['complete_columns'])+' |')
 return header+'\n'.join(parts)+'\n'
def candidate_table():
 parts=['| 案 | 栏目／替补 | 上期前六肖数 | 相对331换肖 | 假设零栏 | 假设全完 | 331回放完整栏 | 近45回放零栏 |','|---|---|---:|---:|---:|---:|---:|---:|']
 for x in cands:
  name=x['id']+('（理论、不上线）' if x['architecture']!='shared' else '（实际331）' if x['id']=='HH00' else '（选）' if x['id']=='HH01' else '');rs=''.join(x['reserves']) or '无';v=x['uniform_model'];slots=x['single']+'；'+''.join(x['pair'])+'；'+''.join(x['triple'])+'；'+rs;parts.append(f"| {name} | {slots} | {len(x['previous_six_overlap'])} | {len(x['changed_formal_relative_to_331'])} | {v['distribution_percent'][0]:.4f}% | {v['distribution_percent'][3]:.4f}% | {x['posthoc_331']['complete_columns']} | {x['posthoc_fixed_windows']['45']['complete_0_1_2_3'][0]} |")
 return '\n'.join(parts)+'\n'
def old_counter_table():
 parts=['| 331比较案 | 性质 | 单 | 二 | 三 | 完整栏 |','|---|---|---|---|---|---:|']
 for x in retro['candidate_counterfactuals']:
  label='最终修订、实际展示' if x['id']=='GG01' else '此前初版，后被修订' if x['id']=='FF01' else '非实际选中对照';parts.append('| '+x['id']+' | '+label+' | '+' | '.join(cell(s) for s in x['slots'])+' | '+str(x['complete_columns'])+' |')
 return '\n'.join(parts)+'\n'
head='''# 331期失败复盘、332期方案与逐期核验\n\n> **口径与边界：**331期由用户提供，并已明确确认前六为**27龍、18牛、03龍、47猴、16兔、14蛇**，第七为**13馬**。这是用户确认，不是官方来源认证；日期、332目标生肖号码映射与赛前状态仍未认证。330和329的前六／第七划分仍只是按顺序推定。第七球不补正码栏目。没有查询或使用332结果，但这不证明赛前。开奖无法保证命中或收益。\n\n## 一、331最终修订案为什么失败\n\n331最终展示GG01为单馬、二狗牛、三狗兔蛇，虎仅替补。按用户确认的前六结算：\n\n| 栏目 | 实际展示 | 前六命中 | 缺失 | 完整？ |\n|---|---|---|---|---|\n| 单肖 | 馬 | 0/1 | 馬 | 否；13馬在第七 |\n| 二肖 | 狗、牛 | 1/2：18牛 | 狗 | 否 |\n| 三肖 | 狗、兔、蛇 | 2/3：16兔、14蛇 | 狗 | 否 |\n\n**零完整栏：单馬0/1、二狗牛1/2缺狗、三狗兔蛇2/3缺狗。**前六虽然出现正式展示中的牛、兔、蛇3肖，但缺共同位狗，使二、三栏一起不完整；馬出在第七，不能补单肖。虎为替补且七球都未出现；前六的龍和猴在全集外，不自动代替正式肖。龍与狗同为奇数0路，但27龍、03龍不是狗，身份不能因同路或奇偶相同就互换。前六0／1／2路为**3／1／2**，因此这次二栏失败并非因为0路球数不足，而是狗的身份缺失。\n\n相对330推定前六，331前六重**牛、猴**2肖；原331修订在设计时只保留330前六的馬、牛，匹配到了牛而未覆盖猴。重肖数量与具体身份是两件事，不能说“重2肖就会命中”。331前六5肖（龍两球）、七球6肖；和值125、跨度44、奇偶3／3。以上331前六／第七由用户确认，而330的球次并未明确确认。\n\n331此前初版FF01事后按同一前六结算：单馬0/1、二鷄牛1/2缺鷄、三鷄龍蛇2/3缺鷄，也为**零完整栏**。原初版与最终修订均保留，不把初版结果当成修订的实际成绩。此前10个已记录的相关结构中，GG05事后套331时三龍兔蛇恰好3/3，只有**1栏**完整；它不是最终选中的331方案，事后对照不能证明其对332更准。\n\n'''
mid='''\n## 二、332人工方案：调整暴露，不承诺命中\n\n| 栏目 | 332方案 | 当前映射下的号码 | 条件说明 |\n|---|---|---|---|\n| 单肖 | **馬** | 01、13、25、37、49 | 五码；331的13馬是第七，不作为本次选馬的预测依据。 |\n| 二肖 | **虎、牛** | 虎05、17、29、41；牛06、18、30、42 | 跨2／0路且一奇一偶；虎缺则断。 |\n| 三肖 | **虎、鷄、羊** | 虎05、17、29、41；鷄10、22、34、46；羊12、24、36、48 | 跨2／1／0路；任一缺失则不完整。 |\n| 仅替补 | **龍** | 03、15、27、39 | 331前六有两球；本次仅替补，不自动补栏。 |\n\n相对331最终修订的正式五肖**馬狗牛兔蛇**，新案去掉狗、兔、蛇，加入虎、鷄、羊，实际换**3肖**；相对331用户确认的前六5肖，正式栏只保留**牛1肖**。六肖全集中龍也属上期前六，但只是替补，不等于正式保留兩肖。选案沿用既有二栏A+B、三栏A+C+D的共享结构；選馬是按不变映射下其五码构成作的取舍，并非因331第七出馬就认定会续出。若目标期映射改变，号码及模型须重算。\n\n### 不能掩盖的结构风险\n\n1. **虎仍是二、三共同位。**虎缺时两栏仍会同时不完整；这次只换了共同身份，没有消除这种结构性风险。馬缺则单栏不完整。零栏当且仅当：**馬缺，且［虎缺，或（牛缺且鷄、羊至少一肖缺）］**。\n2. 无0路时二、三均断（牛、羊分别需0路）；无1路时单、三均断（馬、鷄需1路）；无2路时二、三均断（虎需2路）。三栏全完至少需0／1／2路**2／2／1**球和**2奇3偶**，这些只是必要条件，身份仍须全部正确。\n3. 修订案相对331前六，全栏只可能在重**1或2肖**时出现，但重1或2不保证全完。若零重肖，二栏必断，单肖或三肖仍可能完整；若重3—5肖，全栏不可能。旧331案相对331前六，全栏只可能在重3或4肖时出现；两者换了风险暴露，而非消除了风险。\n4. 如果去掉二、三的共同肖，可以避免“单一共同肖缺失必使二三同断”，但仍可能因不同肖缺失而双断。这会改变既有栏目规则：T14采用6个互不重叠的正式肖、无替补；T15将共享转到单肖与三肖。两者仅作下表理论对照，**没有擅自改规则上线**。\n\n### 模型和事后回放\n\n在**49码等可能、不放回取6码且目标映射不变**的假设下，直接枚举13,983,816种集合，331旧案与332新案完整0／1／2／3栏分布相同，分别为**38.5598%／52.9297%／8.1810%／0.3295%**；两组合都不完整均为**80.6007%**。这只是理想模型，不是已认证的真实开奖概率、收益或预测优势。\n\n仅在“前六相对331零重肖”的条件模型中，旧案零栏28.3348%，新案19.6160%；但旧案全栏可能重3或4，新案只可能重1或2，重肖数实际未知，不能把单个条件的改善当作整体更准。理论T14的零栏／全完为37.7588%／0.0366%，T15为40.9686%／0.3295%；它们减少共同肖暴露的同时有不同代价，并非保证。\n\n新案事后套331：单馬0/1、二虎牛1/2缺虎、三虎鷄羊0/3，同样零完整栏，并非331真实发布成绩。把固定方案套截至331近35／40／45条历史：旧案零栏**11／14／19**，新案**9／12／14**；HH11近45为**13**次。窗口相互重叠，331及历史在选择时已知，非盲测，不能据此宣称新案或HH11在332更准。下表共16个相关结构，含旧案、13个当前规则方案及2个未上线理论方案，不是16次独立试验。\n\n'''
cohort='''\n## 三、上期重肖的历史描述\n\n331前六5肖、七球6肖。资料内同类且后一期已知的**346对**中，前六对前六重0—5肖次数为**8／70／141／107／20／0**；5／5组227对、6／6组133对、6／7组131对分别统计。330→331已计入，330球次仍属推定；331→332不在分母内。筛选是在已知331后进行的探索描述，样本相互重叠、来源未经认证，不能拿历史比例预测下一期，也不能拿第七球补前六栏目。\n\n## 四、每期留存方案的命中和缺失\n\n仅按各期留存版本、各期前六结算，不把替补或第七球自动补栏。291—308来源为留存栏目文件，309—331来源为Git页面快照；来源和保存时点未认证。331记录使用最终修订GG01而非初版。共**38份**，完整0／1／2／3栏为**16／17／4／1**；单、二、三分别完整14／10／4次。共同位缺失17期，但共同位出现也不保证另外身份齐全；这些不是盲测胜率。\n\n'''
tail='''\n**319、322、324是结果已知后的事后重建，单列，不计入38份留存盘：**\n\n'''
end='''\n30份留存盘有明确全集、8份（291—298）全集未知；14期已知全集中有非栏目肖出现在前六。未知全集不能当无替补，非栏目肖也不能自动补栏。历史来源或时点不明、样本交叉、候选事后生成与多次回放，均限制结论；不保证332结果。\n\n## 五、核验与材料\n\n331用户确认球次与冻结的最终页面、38份逐栏结算、3份重建、10个旧候选事后对照均已独立核对；332比较包含16个相关结构，用独立逐号码动态规划和直接枚举交叉核对模型及重肖条件。仅核验内部材料、算术与页面，不认证官方来源、开奖机制、赛前时点、真实微信安全或未来收益。原331修订、初版及其公网清单保留。原331初版和修订本地核验ZIP在当前工作区快照缺失，不冒称已恢复；本次公开材料另行命名。\n\n[38份逐期留存CSV](archive/task305_331_review_332/analysis/historical_display_outcomes.csv) · [3份事后重建CSV](archive/task305_331_review_332/analysis/reconstructed_outcomes_separate.csv) · [331旧候选事后对照](archive/task305_331_review_332/analysis/331_candidates_counterfactual.csv) · [332结构对照](archive/task305_331_review_332/analysis/candidate_comparison.csv) · [332结构明细](archive/task305_331_review_332/analysis/candidate_audit.json) · [331复盘独立核验](archive/task305_331_review_332/analysis/review_independent_qc.json) · [332候选独立核验](archive/task305_331_review_332/analysis/candidate_independent_qc.json) · [直接枚举结果](archive/task305_331_review_332/analysis/brute_model.json) · [重肖分组](archive/task305_331_review_332/analysis/six_sign_repeat_study.json) · [331修订前次复盘](331期重新筛选与330期逐期复盘.md)。\n'''
text=head+old_counter_table()+mid+candidate_table()+cohort+historical_table(records,True)+tail+historical_table(recon,False)+end;report.write_text(text,encoding='utf8')
def html_rows(xs):
 return ''.join('<tr><td>'+str(x['period']%1000)+'</td>'+''.join('<td>'+escape(cell(s))+'</td>' for s in x['slots'])+'<td>'+str(x['complete_columns'])+'</td></tr>' for x in xs)
